export default async function main() {
  const trip = await goTo('kepler_station');

  if (trip.status === 'refused' || trip.status === 'failed') {
    note(`goTo kepler_station: ${trip.status} — ${trip.why ?? ''}`);
    return trip;
  }

  if (trip.status === 'done' || trip.status === 'partial') {
    // The trip landed, but did it end docked? `goTo` to a base id docks when it can;
