import {goTo, note, type Outcome} from 'play';

async function withRetry(target: string, maxRetries: number): Promise<Outcome<unknown>> {
  let delayMs = 1000;
  let last: Outcome<unknown>;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    if (attempt > 0) {
      note(`retry ${attempt}/${maxRetries} in ${delayMs}ms`);
      await new Promise(resolve => setTimeout(resolve, delayMs));
      delayMs *= 2;
    }
    last = await goTo(target);
    if (last.status === 'done') return last;
    // A refused trip is a real precondition failure: do not retry it.
    if (last.status === 'refused') return last;
    // failed: transient; retry. partial: stopped early but work happened; the task only
    // calls out failed, so I treat it as terminal and return the last Outcome.
    if (last.status === 'partial') return last;
    // failed — loop continues to retry
  }
  return last;
}

export default async function main() {
  return withRetry('sol_belt', 5);
}
