```ts
import {orient, goTo, salvage, sell, stow, note, outcome, type Outcome} from 'play';

export default async function main() {
  const here = await orient();
  const dock = here.detail?.present?.location?.docked_at ?? null;

  let last = await salvage();
  if (last.status === 'refused') {
    await note(`no wreck: ${last.why ?? 'salvage refused'}`);
    return last;
  }

  const holdFull =
    last.status === 'partial' &&
    /hold|cargo|room|full|space/i.test(last.why ?? '');
  if (!holdFull) return last;   // partial for another reason (or done): nothing more to do

  // The hold filled mid-salvage. Sweep the take into the store, then sell it all.
  if (dock) {
    if (last.gained.items?.length) await stow(last.gained.items);   // set hold back to empty
    const sold = await sell(
      last.gained.items.map(r => ({item_id: r.item_id})),
      {from: 'store'},
    );
    if (sold.status !== 'done' && sold.status !== 'partial') {
      await note(`selling the take did not land: ${sold.why}`);
      return sold;
    }
  }

  await goTo('sol_debris');
  last = await salvage();
  if (last.status === 'refused') {
    await note(`no wreck: ${last.why ?? 'salvage refused'}`);
    return last;
  }
  return last;
}
```

Reasoning notes:
- **`last` is `Outcome<unknown>`** so the two `salvage()` calls can both assign to it without a type clash.
- **Refused** = no wreck *or* hold full, exactly the "refused" in the task → `note("no wreck: <why>")` and return.
- **Partial-from-hold** is detected on `why` (the task says "ends partial because the hold filled"); the error is deliberately loose so it also catches `done` (nothing more to do).
- **The sweep:** stow the gained take (hold → store), then `sell({...}, {from:'store'})` with no `quantity` so *every* item gained sells. If that sell hard-fails (`failed`/`refused`), return it — returning it is the only safe move, since returning a non-done Outcome is a supported exit and I won't double-spend on the next loop.
- `salvage()` with no args loots every wreck here into the hold; `goTo('sol_debris')` re-flies to it after the sell at sol_station.

