export default async function main() {
  // We fly to sol_nebula first so that `goTo` puts us at the POI where the fight happens.
  const here = await orient();
  const trip = await goTo('sol_nebula');
  if (trip.status !== 'done') return trip;   // not at the POI, so a 2-fight hunt here is pointless

  let result;
  try {
    result = await hunt({fights: 2});        // the fight; any thrown error is caught below
