import {orient, prices, missions, note} from 'play';

export default async function main() {
  // All three reads fire at once, as asked: the present, the live book, the board.
  const [look, market, board] = await Promise.all([orient(), prices(), missions()]);

  // Credits from the present.
  const credits = look.now?.credits ?? 0;

  // The item_id with the highest best_buy in the live book here.
  let bestItem = '';
  let bestBuy = 0;
  let hasQuote = false;
  for (const q of market.detail?.quotes ?? []) {
    if (!hasQuote || q.best_buy > bestBuy) {
      bestItem = q.item_id;
      bestBuy = q.best_buy;
      hasQuote = true;
    }
  }

  // How many missions are on the board, whatever shape the detail takes.
  const d = board.detail as unknown;
  let missionCount = 0;
  if (Array.isArray(d)) {
    missionCount = d.length;
  } else if (d && typeof d === 'object') {
    const m = (d as {missions?: unknown[]}).missions;
    missionCount = Array.isArray(m) ? m.length : 0;
  }

  await note(
    `credits ${credits}; top bid ${bestItem || '(none)'} at ${bestBuy}; ${missionCount} mission(s) on the board`,
  );

  return market;
}
```

