import {
  orient,
  missions,
  acceptMission,
  completeMissions,
  note,
  outcome,
  type Outcome,
} from 'play';
import type { MissionInfo } from '@spacemolt/lib';

function isBoardMission(m: MissionInfo): boolean {
  return m.type === 'board';
}

export default async function main() {
  await orient();

  const board = await missions();
  if (board.status !== 'done') {
    await note(`missions() did not return a board: ${board.why ?? board.status}`);
  }

  // Current missions; free slots = the capacity minus the ones already active.
  let active: MissionInfo[] = board.detail?.missions ?? [];
  const capacity = board.detail?.max_missions ?? 0;
  let free = Math.max(0, capacity - active.length);

  // Board rows only, reward >= 100. No stable value order published, so take in board order.
  const candidates = active
    .filter(isBoardMission)
    .filter(m => (m.reward ?? 0) >= 100);

  let accepted = 0;
  for (const m of candidates) {
    if (free <= 0) {
      await note(`free slots filled after ${accepted} accept(s); ${candidates.length - accepted} higher-ignored by slot cap`);
      break;
    }
    const a = await acceptMission(m.id);
    if (a.status !== 'done') {
      await note(`acceptMission(${m.id}) not done: ${a.why ?? a.status}; stopping acceptance`);
      break;
    }
    accepted += 1;
    free -= 1;
  }
  await note(`accepted ${accepted} board mission(s) (capacity ${capacity}, ${free} slot(s) still open)`);

  const done = await completeMissions();
  if (done.status !== 'done') {
    await note(`completeMissions() ${done.status}: ${done.why ?? done.did ?? 'no reason given'}`);
  }

  return outcome(
    `accepted ${accepted} board mission(s) and then completed missions`,
    'done',
    { accepted }
  );
}

