  const finish = async (result: Outcome<unknown>): Promise<Outcome<unknown>> => {
    try {
      const look = await orient();
      await note(`Current credits: ${look.now?.credits ?? 'unknown'}`);
    } catch {
      // ignore: the note is the best effort
    }
    return result;
  };

