    const copper = settled.filter(r => r.item_id === 'copper_ore');
    const sellOutcome = await sell(copper, { from: 'store' });

    // 3. Service the ship.
    svc = await service();

    // 4. Complete missions (a not-done result there is fine).
    await completeMissions();
  } catch (e) {
    // Even on a throw, ensure the credits note is the last thing, then return the
